<!--
  Ficheiro: src/views/LiveView.vue
  Tipo: Página Vue.
  Função: Biblioteca TV com pesquisa, filtros, vistas, detalhe e edição.
-->
<script setup lang="ts">
import { computed,onMounted,ref,watch } from "vue";import BaseEmptyState from "@/components/base/BaseEmptyState.vue";import BasePageHeader from "@/components/base/BasePageHeader.vue";import BasePagination from "@/components/base/BasePagination.vue";import ChannelCard from "@/components/live/ChannelCard.vue";import ChannelFilters from "@/components/live/ChannelFilters.vue";import ChannelDetailDialog from "@/components/live/ChannelDetailDialog.vue";import ChannelEditDialog from "@/components/live/ChannelEditDialog.vue";import { channelRepository,countryRepository,languageRepository,streamLinkRepository,tagRepository,tvCategoryRepository } from "@/domain/repositories";import type { ChannelRecord,NamedRecord,StreamLinkRecord,TvCategoryRecord } from "@/types/records";
const channels=ref<ChannelRecord[]>([]),page=ref(1),pages=ref(1),total=ref(0);const loading=ref(true),error=ref("");const search=ref(""),country=ref(""),category=ref(""),quality=ref(""),status=ref(""),favorite=ref("");const view=ref<"grid"|"list"|"compact">("grid");const countries=ref<NamedRecord[]>([]),languages=ref<NamedRecord[]>([]),tags=ref<NamedRecord[]>([]),categories=ref<TvCategoryRecord[]>([]);const selected=ref<ChannelRecord|null>(null),editing=ref<ChannelRecord|null>(null),links=ref<StreamLinkRecord[]>([]),linksLoading=ref(false);let timer:ReturnType<typeof setTimeout>;
const filterCount=computed(()=>[search.value,country.value,category.value,quality.value,status.value,favorite.value].filter(Boolean).length);const esc=(v:string)=>v.replaceAll("\\","\\\\").replaceAll('"','\\"');function filter(){const t=["cemiterio = false"];if(search.value.trim()){const q=esc(search.value.trim());t.push(`(nome ~ "${q}" || tvg_name ~ "${q}" || tvg_id ~ "${q}" || epg_id ~ "${q}" || playlist_origem ~ "${q}")`)}if(country.value)t.push(`pais = "${country.value}"`);if(category.value)t.push(`categoria = "${category.value}"`);if(quality.value)t.push(`qualidade = "${quality.value}"`);if(status.value)t.push(`ativo = ${status.value==="active"}`);if(favorite.value)t.push(`favorito = ${favorite.value==="yes"}`);return t.join(" && ")}
async function load(){loading.value=true;error.value="";try{const r=await channelRepository.list({page:page.value,perPage:18,filter:filter(),sort:"ordem,nome",expand:"pais,categoria,idiomas,tags"});channels.value=r.items;pages.value=r.totalPages||1;total.value=r.totalItems}catch(c){error.value=c instanceof Error?c.message:String(c)}finally{loading.value=false}}
async function lookups(){const [p,c,i,t]=await Promise.all([countryRepository.list({page:1,perPage:250,filter:"ativo = true",sort:"ordem,nome"}),tvCategoryRepository.list({page:1,perPage:100,filter:"ativo = true",sort:"ordem,nome"}),languageRepository.list({page:1,perPage:100,filter:"ativo = true",sort:"ordem,nome"}),tagRepository.list({page:1,perPage:200,filter:"ativo = true",sort:"ordem,nome"})]);countries.value=p.items;categories.value=c.items;languages.value=i.items;tags.value=t.items}
async function open(c:ChannelRecord){selected.value=c;linksLoading.value=true;try{const r=await streamLinkRepository.list({page:1,perPage:100,filter:`canal_tv = "${c.id}"`,sort:"prioridade"});links.value=r.items}finally{linksLoading.value=false}}
function saved(c:ChannelRecord){channels.value=channels.value.map(x=>x.id===c.id?c:x);if(selected.value?.id===c.id)selected.value=c;editing.value=null}function archived(id:string){channels.value=channels.value.filter(x=>x.id!==id);if(selected.value?.id===id)selected.value=null;editing.value=null;total.value=Math.max(0,total.value-1)}function clear(){search.value=country.value=category.value=quality.value=status.value=favorite.value="";page.value=1;void load()}
watch([search,country,category,quality,status,favorite],()=>{clearTimeout(timer);timer=setTimeout(()=>{page.value=1;void load()},300)});onMounted(()=>{void Promise.all([load(),lookups()])});
</script>
<template><BasePageHeader eyebrow="Em direto" title="TV e streams" :description="`${total} canais na biblioteca`"><template #actions><button class="button button-primary" type="button" disabled title="Importação M3U será implementada no próximo incremento">⇩ Importar M3U, em breve</button></template></BasePageHeader><div v-if="error" class="form-alert form-alert-error" role="alert">{{error}}</div><ChannelFilters v-model:search="search" v-model:country="country" v-model:category="category" v-model:quality="quality" v-model:status="status" v-model:favorite="favorite" :countries="countries" :categories="categories" :count="filterCount" @clear="clear"/><div class="section-heading"><div><p class="eyebrow">Biblioteca</p><h2>Canais TV</h2></div><div class="view-switch" role="group" aria-label="Vista dos canais"><button type="button" :class="{'is-active':view==='grid'}" @click="view='grid'">▦ Grelha</button><button type="button" :class="{'is-active':view==='list'}" @click="view='list'">☰ Lista</button><button type="button" :class="{'is-active':view==='compact'}" @click="view='compact'">≡ Compacta</button></div></div><div v-if="loading" class="page-loading"><span class="loader"/></div><div v-else-if="channels.length" class="live-collection" :class="`is-${view}`"><ChannelCard v-for="item in channels" :key="item.id" :channel="item" :view="view" @open="open" @edit="editing=$event"/></div><BaseEmptyState v-else icon="▣" title="Sem canais" description="Não existem canais para estes filtros."/><BasePagination :page="page" :pages="pages" label="Paginação dos canais" @change="page=$event;load()"/><ChannelDetailDialog :channel="selected" :links="links" :loading="linksLoading" @close="selected=null" @edit="editing=$event"/><ChannelEditDialog :channel="editing" :countries="countries" :languages="languages" :tags="tags" :categories="categories" @close="editing=null" @saved="saved" @archived="archived"/></template>
